CREATE TABLE weather.ttl_observations (observed_at DateTime, station_id String, temperature_c Float64) ENGINE=MergeTree ORDER BY(station_id, observed_at) TTL observed_at + INTERVAL 30 DAY RECOMPRESS CODEC(ZSTD(3)), observed_at + INTERVAL 60 DAY TO VOLUME 'warm', observed_at + INTERVAL 365 DAY DELETE SETTINGS storage_policy='tiered',min_rows_for_wide_part=0,min_bytes_for_wide_part=0,index_granularity=256
